import {esc} from './models.js?v=0.19.0';
export function advancedCourseHTML(course,track){
 const complete=course.status==='complete',multiple=course.modules.length>1,byId=new Map(course.lessons.map(l=>[l.id,l]));
 return `<div class="breadcrumb"><a href="#map/${track}">Learning path</a><span aria-hidden="true">/</span><span>Course coverage</span></div><span class="pill">${complete?'Defined course available':multiple?course.modules.length+' modules available':'Starter module available'}</span><h1>${esc(course.title)}</h1><p class="map-intro">${esc(course.subtitle)}</p><p>${course.lessons.length} lessons in ${course.modules.length} ${multiple?'modules':'module'} are ready.${complete?'':' The full advanced course is still being built.'}</p><div class="step-actions"><a class="primary" href="#learn/${course.id}/${course.lessons[0].id}/understand">Start the first lesson →</a><a href="#prepare/${course.id}">Review the preparation</a></div><p class="notice"><strong>Earlier courses</strong><br>${esc(course.prerequisites.join(' · '))}</p><h2>Course lessons</h2>${course.modules.map((m,i)=>`<section class="available-module"><h3>${i+1}. ${esc(m.title)}</h3><ol class="topics">${m.lessonIds.map(id=>{const l=byId.get(id);return `<li><a href="#learn/${course.id}/${l.id}/understand">${esc(l.title)}</a></li>`;}).join('')}</ol></section>`).join('')}<details class="planned-steps"><summary>${complete?'Scope limits and further study':'Later course topics · not yet complete'}</summary><p>${complete?esc(course.scopeNote):'These topics come after the available lessons.'}</p><ol>${(complete?course.beyondScope:course.nextTopics).map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details><details class="planned-steps"><summary>References used to check scope and relationships</summary><p>Teaching text and examples were written for this app. These reference courses are not completed or replaced by the available modules.</p><ul>${course.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></li>`).join('')}</ul></details>`;
}
